namespace DocSummary.Models;

public class SummarizeRequest
{
    public required string DocumentText { get; set; }
}

namespace DocSummary.Models;

public class SummarizeResponse
{
    public required string Summary { get; set; }
}

namespace DocSummary.Services;

public interface IDocumentSummaryService
{
    string Summarize(string documentText);
}

namespace DocSummary.Services;

/// <summary>
/// Produces a concise extractive summary by scoring sentences on length and position,
/// then returning the top-ranked ones in their original order.
/// </summary>
public class ExtractiveSummaryService : IDocumentSummaryService
{
    private const int MaxSentences = 3;

    public string Summarize(string documentText)
    {
        if (string.IsNullOrWhiteSpace(documentText))
            return string.Empty;

        var sentences = SplitIntoSentences(documentText);

        if (sentences.Length <= MaxSentences)
            return string.Join(" ", sentences);

        // Score each sentence: longer sentences that appear earlier are ranked higher.
        var scored = sentences
            .Select((sentence, index) => new
            {
                Sentence = sentence,
                Index = index,
                Score = sentence.Split(' ', StringSplitOptions.RemoveEmptyEntries).Length
                        * (1.0 / (index + 1))
            })
            .OrderByDescending(s => s.Score)
            .Take(MaxSentences)
            .OrderBy(s => s.Index)
            .Select(s => s.Sentence);

        return string.Join(" ", scored);
    }

    private static string[] SplitIntoSentences(string text)
    {
        return text.Split(['.', '!', '?'], StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries)
                   .Where(s => s.Length > 0)
                   .Select(s => s + ".")
                   .ToArray();
    }
}

using DocSummary.Models;
using DocSummary.Services;
using Microsoft.AspNetCore.Mvc;

namespace DocSummary.Controllers;

[ApiController]
[Route("api/[controller]")]
public class SummaryController : ControllerBase
{
    private readonly IDocumentSummaryService _summaryService;

    public SummaryController(IDocumentSummaryService summaryService)
    {
        _summaryService = summaryService;
    }

    [HttpPost]
    public ActionResult<SummarizeResponse> Summarize([FromBody] SummarizeRequest request)
    {
        if (string.IsNullOrWhiteSpace(request.DocumentText))
            return BadRequest("DocumentText must not be empty.");

        var summary = _summaryService.Summarize(request.DocumentText);

        return Ok(new SummarizeResponse { Summary = summary });
    }
}

